WITH parsed AS (SELECT id, customer_id, created_at, items, ship_to, attributes, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS used_spring10, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price FROM carts) SELECT customer_id, COUNT(*) AS event_count, ROUND(AVG(max_item_price), 2) AS avg_max_item_price, MIN(max_item_price) AS min_max_item_price FROM parsed GROUP BY customer_id HAVING ROUND(AVG(max_item_price), 2) > 0
